-- Priority-payment matching for The Grifflist.
-- Apply in Supabase SQL Editor AFTER the existing song_requests and kofi_tips tables exist.
-- Payment references are generated by Postgres, never trusted from the browser.
-- Only verified CAD Ko-fi webhook records can automatically mark a priority request paid.

alter table public.song_requests
  add column if not exists payment_reference text,
  add column if not exists payment_method text,
  add column if not exists payment_status text not null default 'not_required',
  add column if not exists payment_provider text,
  add column if not exists payment_provider_reference text,
  add column if not exists payment_verified_at timestamptz;

alter table public.song_requests
  drop constraint if exists song_requests_payment_status_check;
alter table public.song_requests
  add constraint song_requests_payment_status_check
  check (payment_status in ('not_required','pending','paid','unmatched','failed','refunded'));

alter table public.song_requests
  drop constraint if exists song_requests_payment_method_check;
alter table public.song_requests
  add constraint song_requests_payment_method_check
  check (payment_method is null or payment_method in ('kofi','paypal','etransfer'));

create unique index if not exists song_requests_payment_reference_unique
  on public.song_requests(payment_reference)
  where payment_reference is not null;
create unique index if not exists song_requests_payment_provider_reference_unique
  on public.song_requests(payment_provider, payment_provider_reference)
  where payment_provider_reference is not null;

create or replace function public.prepare_priority_payment_request()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_method text;
  v_reference text;
  v_attempt integer := 0;
begin
  -- Never accept client-supplied payment state or reference.
  new.payment_reference := null;
  new.payment_method := null;
  new.payment_provider := null;
  new.payment_provider_reference := null;
  new.payment_verified_at := null;
  new.payment_status := 'not_required';

  if coalesce(new.note,'') ~* '\[PRIORITY TIP (PENDING|REPORTED)[^]]*VERIFY PAYMENT\]' then
    v_method := lower((regexp_match(coalesce(new.note,''), 'Method:\s*(kofi|paypal|etransfer)', 'i'))[1]);
    if v_method is not null then
      new.payment_method := v_method;
      new.payment_status := 'pending';
      loop
        v_reference := 'GRF-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));
        v_attempt := v_attempt + 1;
        exit when not exists (
          select 1 from public.song_requests r where r.payment_reference = v_reference
        );
        if v_attempt >= 10 then
          raise exception 'Could not allocate a unique payment reference';
        end if;
      end loop;
      new.payment_reference := v_reference;
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists prepare_priority_payment_request on public.song_requests;
create trigger prepare_priority_payment_request
before insert on public.song_requests
for each row execute function public.prepare_priority_payment_request();

-- A request's unguessable tracking token reveals only its own payment reference/status.
create or replace function public.get_request_payment_details(p_tracking_token uuid)
returns table(payment_reference text, payment_status text)
language sql
stable
security definer
set search_path = public
as $$
  select r.payment_reference, r.payment_status
  from public.song_requests r
  where r.tracking_token = p_tracking_token
  limit 1;
$$;
revoke all on function public.get_request_payment_details(uuid) from public;
grant execute on function public.get_request_payment_details(uuid) to anon, authenticated;

-- Match Ko-fi events only when:
-- 1) the webhook has already verified and inserted the event into kofi_tips;
-- 2) currency is CAD and amount is at least $5 CAD;
-- 3) the supporter message contains the exact server-generated request reference;
-- 4) the request is still pending and its selected method is Ko-fi.
create or replace function public.match_kofi_tip_to_priority_request()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_reference text;
begin
  if upper(coalesce(new.currency,'')) <> 'CAD' or coalesce(new.amount,0) < 5 then
    return new;
  end if;

  v_reference := upper((regexp_match(coalesce(new.supporter_message,''), '(?i)(GRF-[A-F0-9]{8})'))[1]);
  if v_reference is null then
    return new;
  end if;

  update public.song_requests r
     set payment_status = 'paid',
         payment_provider = 'kofi',
         payment_provider_reference = new.message_id,
         payment_verified_at = coalesce(new.received_at, now())
   where r.payment_reference = v_reference
     and r.payment_method = 'kofi'
     and r.payment_status = 'pending'
     and r.payment_provider_reference is null;

  return new;
end;
$$;

drop trigger if exists match_kofi_tip_to_priority_request on public.kofi_tips;
create trigger match_kofi_tip_to_priority_request
after insert on public.kofi_tips
for each row execute function public.match_kofi_tip_to_priority_request();

-- The provider event is inserted by the verified server-side webhook.
-- Do not grant browser roles write access to payment fields.
comment on column public.song_requests.payment_reference is
  'Server-generated, non-secret reference for matching verified payment provider events.';
comment on column public.song_requests.payment_status is
  'Payment status; only verified server-side provider events may set paid.';
